<script>
 import ResearchToolbar from './ResearchToolbar.svelte';
 import ResearchInspector from './ResearchInspector.svelte';
 import SourcePreview from './SourcePreview.svelte';
 import HumanSelectedMoment from './HumanSelectedMoment.svelte';
 import {strategyReturnContext} from '../../lib/defiant-location.js';
 import {untrack,onDestroy,tick} from 'svelte';
 import DefiantDiscovery from './DefiantDiscovery.svelte';
 import DefiantClip from './DefiantClip.svelte';
 import DefiantPreprocess from './DefiantPreprocess.svelte';
 let {state:workspace,location,request,onSaved,onNavigate,onDirtyChange=()=>{}}=$props();
 let briefSection=$state(null),briefTitle=$state(null),sourceHeading=$state(null);
 let browseOpen=$state(false),focusSourceId=$state('');
 $effect(()=>{if(focusSourceId&&source?.id===focusSourceId&&sourceHeading)untrack(()=>{focusSourceId='';sourceHeading.focus({preventScroll:true});});});
 function selectSource(id){if(dirty){navigate({sourceId:id});return;}if(!source){browseOpen=false;focusSourceId=id;}navigate({sourceId:id});}
 function resetFilters(){navigate({query:'',cohort:'',workstreamId:'',inboxStage:'',recordingId:''});}
 let projected=$state(null),projectionSequence=0;
 const box=$derived(projected||workspace.inbox||{sources:[],matches:[],recordings:[],workstreams:[]});
 const source=$derived(box.selected?.id===location.sourceId?box.selected:box.sources.find(s=>s.id===location.sourceId));
 const catalog=$derived(box.catalogGroups?.[0]);
 const catalogRecordings=$derived(catalog?box.recordings.filter(r=>catalog.recordingIds.includes(r.id)):box.recordings);
 const match=$derived(box.matches.find(m=>m.sourceId===source?.id));
 let loaded=$state(''),loadedRevision=$state(0),recordingId=$state(''),workstreamId=$state(''),stage=$state('new'),rationale=$state(''),base=$state(''),note=$state('');
 let busy=$state(false),error=$state(''),notice=$state(''),preview=$state(null),intent=$state(null),unknown=$state(false),reportTitle=$state('');
 let humanMomentDirty=$state(false),humanMoment=$state(null);
 let momentDirty=$state(false),selectedMoment=$state(null),selectedAnalysisId=$state(''),clipMoment=$state(null);
 let matchDetailsOpen=$state(false),analysisToolsOpen=$state(false);
 let analysisDisclosureSource='',analysisDisclosureMoment='';
 $effect(()=>{const sourceId=source?.id||'',momentId=selectedMoment?.id||'';untrack(()=>{if(sourceId!==analysisDisclosureSource){analysisDisclosureSource=sourceId;analysisDisclosureMoment='';analysisToolsOpen=false;return;}if(momentId&&momentId!==analysisDisclosureMoment){analysisDisclosureMoment=momentId;analysisToolsOpen=true;}});});
 $effect(()=>{source?.id;untrack(()=>{matchDetailsOpen=!match;});});
 let clipDirty=$state(false),discoveryDirty=$state(false),packKind=$state('nipsey-example');
 let alive=true;onDestroy(()=>{alive=false;onDirtyChange(false);});
 async function refreshProjection(){const ticket=++projectionSequence;try{const result=await request('/inbox'+(location.sourceId?'?sourceId='+encodeURIComponent(location.sourceId):''));if(alive&&ticket===projectionSequence)projected=result;}catch(e){if(alive&&ticket===projectionSequence)error=e.message;}}
 $effect(()=>{workspace.revision;location.sourceId;untrack(()=>void refreshProjection());});
 const proposalDirty=$derived(JSON.stringify([recordingId,workstreamId,stage,rationale])!==base&&Boolean(loaded));
 const dirty=$derived(clipDirty||momentDirty||humanMomentDirty||discoveryDirty||proposalDirty||Boolean(note.trim()||reportTitle.trim()||intent||preview));
 $effect(()=>onDirtyChange(dirty));
 function adopt(){loaded=source?.id||'';loadedRevision=match?.revision||0;recordingId=match?.recordingId||'';workstreamId=match?.workstreamId||'';stage=match?.stage||'new';rationale=match?.rationale||'';base=JSON.stringify([recordingId,workstreamId,stage,rationale]);}
 $effect(()=>{source?.id;match?.revision;untrack(()=>{if(!proposalDirty&&!intent)adopt();});});
 function navigate(next){if(dirty){error='Save or clear your working text before changing the inbox selection.';return;}onNavigate({...location,...next,...(next.sourceId&&next.sourceId!==location.sourceId?{clipId:'',momentId:''}:{}),view:'inbox'});}
 const rows=$derived.by(()=>{const q=(location.query||'').toLowerCase().trim();return box.sources.filter(s=>{const m=box.matches.find(x=>x.sourceId===s.id),r=box.recordings.find(x=>x.id===m?.recordingId);return (!location.cohort||location.cohort==='all'||s.cohorts?.includes(location.cohort))&&(!location.workstreamId||m?.workstreamId===location.workstreamId)&&(!location.inboxStage||m?.stage===location.inboxStage)&&(!location.recordingId||m?.recordingId===location.recordingId)&&(!q||[s.title,s.creator,s.creatorHandle,r?.title].some(x=>x?.toLowerCase().includes(q)));}).sort((a,b)=>(latestObservation(b,'views')?.value??-1)-(latestObservation(a,'views')?.value??-1));});
 const notes=$derived(workspace.annotations.filter(a=>a.target?.kind==='source'&&a.target.id===source?.id));
 function latestObservation(s,metric){const time=o=>Date.parse(o.observedAt)||Number(o.observedAt)||0;return [...(s.observations||[])].filter(o=>o.metric===metric).sort((a,b)=>time(b)-time(a))[0];}
 function count(s,metric){const n=latestObservation(s,metric)?.value;return typeof n==='number'?n.toLocaleString():'Unknown';}
 async function inspect(){if(busy||unknown)return;busy=true;error='';try{const value=await request('/inbox/import/preview',{method:'POST',body:JSON.stringify({kind:packKind})});if(alive)preview=value;}catch(e){if(alive)error=e.message;}finally{if(alive)busy=false;}}
 async function send(path,payload,kind){if(busy||unknown)return;intent={path,kind,body:{expectedRevision:workspace.revision,idempotencyKey:crypto.randomUUID(),...payload}};await submit();}
 async function submit(){if(busy||!intent)return;busy=true;error='';notice='';try{const ack=await request(intent.path,{method:'POST',body:JSON.stringify(intent.body)});if(!alive)return;const kind=intent.kind;intent=null;unknown=false;if(kind==='import')preview=null;if(kind==='note')note='';if(kind==='match'){loadedRevision=ack.match.revision;base=JSON.stringify([recordingId,workstreamId,stage,rationale]);}if(kind==='report')reportTitle='';notice=kind==='import'?'Example research pack saved':kind==='match'?'Proposed match saved':kind==='note'?'Shared note saved':'Report saved';try{await onSaved(ack);if(kind==='report')onNavigate({...location,view:'report',reportId:ack.report.id});}catch{error='Your save succeeded. Reload to see the saved references.';}}catch(e){if(!alive)return;error=e.status===409?'Saved work changed. Your text is retained. Reload current references and compare before saving again.':e.message;unknown=!(Number.isInteger(e.status)&&e.status>=400&&e.status<500);if(!unknown)intent=null;}finally{if(alive)busy=false;}}
 function saveMatch(){void send('/inbox/sources/'+encodeURIComponent(source.id)+'/match',{expectedMatchRevision:loadedRevision,match:{recordingId,workstreamId,stage,rationale}},'match');}
 function saveNote(){void send('/annotations',{annotation:{target:{kind:'source',id:source.id},kind:'note',text:note,labels:[],evidenceIds:[]}},'note');}
 function report(){if(!source||(!match&&!selectedMoment&&!humanMoment))return;void send('/reports',{report:{title:reportTitle.trim()||(source.provenance?.commit?source.title:'Creator source planning brief'),thesis:'',returnContext:strategyReturnContext({...location,origin:'catalog'}),planIds:[],sourceRefs:[source.id],matchRefs:match?[{sourceId:source.id,id:match.id,revision:match.revision}]:[],...(location.clipId?{clipRefs:[{artifactId:location.clipId}]}:{}),...(humanMoment?{momentRefs:[{kind:'human-selected',momentId:humanMoment.id,revision:humanMoment.revision}]}:selectedMoment?{momentRefs:[{analysisId:selectedAnalysisId,momentId:selectedMoment.id,revision:selectedMoment.revision}]}:{})}},'report');}
 async function focusBrief(){await tick();briefSection?.scrollIntoView({behavior:'smooth',block:'start'});briefTitle?.focus({preventScroll:true});}
 async function reload(){try{await onSaved();}catch(e){error=e.message;}}
 function clear(){if(unknown||busy)return;note='';reportTitle='';preview=null;intent=null;error='';adopt();}
</script>
<section class="video-inbox" aria-label="Creator videos inbox">
 <header class="catalog-header"><div><h2>{catalog?.artist||'Artist catalog'}</h2><p class="research-meta">{#if catalog}{catalog.sourceIds.length} retained supplied sources · {catalog.recordingIds.length} recordings · unverified reference{:else}Choose a recording and inspect a source{/if}</p></div><span class="journey-label">CATALOG</span></header>
 {#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if unknown}<p>The reply was interrupted. Keep this request to check its outcome.</p><button disabled={busy} onclick={submit}>Retry same save</button>{:else if error}<button disabled={busy} onclick={reload}>Reload current references</button>{/if}
 {#if preview}<section class="import" aria-label="Source import preview"><h3>{preview.kind==='nipsey-historical20'?'Historical sample · 20 supplied sources':'Nipsey catalog discovery example'}</h3><p>{Object.entries(preview.counts).map(([kind,c])=>`${kind}: ${c.new} new, ${c.unchanged} unchanged, ${c.conflicting} conflicting`).join(' · ')}</p>{#each preview.warnings as warning(warning)}<p>{warning}</p>{/each}<button disabled={busy||unknown||Object.values(preview.counts).some(c=>c.conflicting)} onclick={()=>send('/inbox/import',{kind:preview.kind,previewDigest:preview.previewDigest,expectedRevision:preview.expectedRevision},'import')}>Add these sources</button><button disabled={busy||unknown} onclick={()=>preview=null}>Cancel import</button></section>{/if}

 {#if !box.sources.length}<div class="empty"><h3>Your source inbox is empty</h3><p>Preview the supplied Nipsey research pack to begin. No videos are downloaded and no sources are marked cleared.</p><details class="pack-tools inspector-section"><summary>Reference packs</summary><label>Reference pack<select bind:value={packKind} disabled={busy||unknown||dirty}><option value="nipsey-example">Nipsey example · 45 supplied sources</option><option value="nipsey-historical20">Historical sample · 20 supplied sources</option></select></label><button class="secondary" disabled={busy||unknown||dirty} onclick={inspect}>{packKind==='nipsey-example'?'Preview Nipsey example pack':'Preview historical sample pack'}</button></details> <DefiantDiscovery {request} revision={workspace.revision} onSaved={onSaved} onDirtyChange={value=>discoveryDirty=value}/></div>
 {:else}
 <ResearchToolbar label="Catalog research controls"><label class="toolbar-grow">Search title, creator or song<input type="search" value={location.query||''} disabled={dirty||busy} onchange={e=>navigate({query:e.currentTarget.value})}/></label><label>Catalog recording<select aria-label="Catalog recording" value={location.recordingId||''} disabled={dirty||busy} onchange={e=>navigate({origin:'catalog',recordingId:e.currentTarget.value,sourceId:'',momentId:'',clipId:''})}><option value="">All recordings</option>{#each catalogRecordings as recording(recording.id)}<option value={recording.id}>{recording.title}</option>{/each}</select></label><details class="source-tools"><summary>More source tools</summary><div class="source-tools-panel"><details><summary>Filter sources</summary><div class="toolbar-panel"><label>Cohort<select value={location.cohort||'all'} disabled={dirty||busy} onchange={e=>navigate({cohort:e.currentTarget.value})}><option value="all">All sources</option><option value="supplied-2026">2026 supplied pack</option><option value="historical-sample">Historical samples</option><option value="youtube-discovery">YouTube discovery</option></select></label><label>Workstream<select value={location.workstreamId||''} disabled={dirty||busy} onchange={e=>navigate({workstreamId:e.currentTarget.value})}><option value="">All workstreams</option>{#each box.workstreams as w(w.id)}<option value={w.id}>{w.name}</option>{/each}</select></label><label>Stage<select value={location.inboxStage||''} disabled={dirty||busy} onchange={e=>navigate({inboxStage:e.currentTarget.value})}><option value="">All stages</option>{#each ['new','considering','selected','parked'] as value(value)}<option {value}>{value}</option>{/each}</select></label><label>Recording<select value={location.recordingId||''} disabled={dirty||busy} onchange={e=>navigate({recordingId:e.currentTarget.value})}><option value="">All recordings</option>{#each box.recordings as r(r.id)}<option value={r.id}>{r.title}</option>{/each}</select></label><button disabled={dirty||busy} onclick={resetFilters}>Reset filters</button></div></details><details class="pack-tools inspector-section"><summary>Reference packs</summary><label>Reference pack<select bind:value={packKind} disabled={busy||unknown||dirty}><option value="nipsey-example">Nipsey example · 45 supplied sources</option><option value="nipsey-historical20">Historical sample · 20 supplied sources</option></select></label><button class="secondary" disabled={busy||unknown||dirty} onclick={inspect}>{packKind==='nipsey-example'?'Preview Nipsey example pack':'Preview historical sample pack'}</button></details> <DefiantDiscovery {request} revision={workspace.revision} onSaved={onSaved} onDirtyChange={value=>discoveryDirty=value}/><p class="research-meta">Recording matches are proposals. Reference pack: {catalog?.referenceCounts.sources||45} supplied sources / {catalog?.referenceCounts.recordings||12} recordings; source counts retain their observation dates.</p></div></details></ResearchToolbar>
 <p class="result-count" role="status">{rows.length} of {box.sources.length} sources · latest reported views{#if !rows.length} <button class="reset-source-filters" disabled={dirty||busy} onclick={resetFilters}>Reset source filters</button>{/if}</p>
 <div class="inbox-layout" class:has-selection={Boolean(source)}><details class="source-browser" open={!source||browseOpen} ontoggle={e=>{if(source)browseOpen=e.currentTarget.open;}}><summary>Browse sources ({rows.length})</summary><div class="table-scroll"><table><caption>Creator video sources</caption><thead><tr><th scope="col">Source / creator</th><th scope="col">Proposed recording</th><th scope="col">Views</th><th scope="col">Stage</th></tr></thead><tbody>{#each rows as s(s.id)}{@const m=box.matches.find(m=>m.sourceId===s.id)}<tr class={{chosen:source?.id===s.id}}><th scope="row"><button disabled={busy||dirty} aria-pressed={source?.id===s.id} onclick={()=>selectSource(s.id)}>{s.title}</button><small>{s.creator}</small></th><td>{box.recordings.find(r=>r.id===m?.recordingId)?.title||'Unmatched'}</td><td>{count(s,'views')}</td><td>{m?.stage||'new'}</td></tr>{:else}<tr><td colspan="4">No matching sources. Reset source filters above to see your inbox.</td></tr>{/each}</tbody></table></div></details>
 {#if source}<ResearchInspector label="Source inspector" selected={Boolean(source)}>{#if source}
 <div class="inspector-heading"><h3 bind:this={sourceHeading} tabindex="-1">{source.title}</h3></div><p>{source.creator} · {source.publishedAt||'Date unknown'}</p>
 <div class="source-workspace"><div class="inspector-composition"><div class="source-reading"><section class="inspector-step" aria-label="Review source"><h4>1. Review the source</h4>
 {#key source.id}<SourcePreview {source}/>{/key}<details class="source-evidence"><summary>Source evidence and provenance</summary><dl><dt>Likes</dt><dd>{count(source,'likes')} · {latestObservation(source,'likes')?.method==='youtube-data-api'?'YouTube API':latestObservation(source,'likes')?'Supplied, observation date unknown':'Not reported'}</dd><dt>Comments</dt><dd>{count(source,'comments')} · {latestObservation(source,'comments')?.method==='youtube-data-api'?'YouTube API':latestObservation(source,'comments')?'Supplied, observation date unknown':'Not reported'}</dd><dt>Supplied hook, not a verified claim</dt><dd>{source.narrativeHook}</dd><dt>Reference</dt><dd>{#if source.provenance?.commit}defiant-os · {source.provenance.commit.slice(0,7)} · row {source.original?.rank||'unknown'}{:else if source.provenance?.kind==='supplied-historical-sample'}Supplied historical sample · unverified{:else}YouTube discovery{/if}</dd>{#if source.liveMetadata}<dt>YouTube API checked</dt><dd>{source.liveMetadata.observedAt}</dd>{/if}</dl>
 {#if source.observationHistory?.length}<details><summary>YouTube observation history ({source.observationHistory.length})</summary><p>API observations expire after 30 days. Missing counts remain unknown; these observations do not establish a trend.</p><table class="observation-history" aria-label="YouTube observation history"><thead><tr><th>Checked</th><th>Views</th><th>Likes</th><th>Comments</th></tr></thead><tbody>{#each source.observationHistory as observation(observation.runId)}<tr><td>{observation.observedAt}</td>{#each ['views','likes','comments'] as metric(metric)}<td>{typeof observation.statistics[metric]==='number'?observation.statistics[metric].toLocaleString():'Unknown'}</td>{/each}</tr>{/each}</tbody></table></details>{/if}
 {#if source.observations.some(o=>o.method==='supplied-example')}<details><summary>Imported counts · observation date unknown</summary><dl>{#each source.observations.filter(o=>o.method==='supplied-example') as observation(observation.metric)}<dt>{observation.metric}</dt><dd>{observation.value.toLocaleString()} · Supplied example, not independently verified</dd>{/each}</dl></details>{/if}
 {#each source.suppliedReferences||[] as reference(reference.packId)}<details><summary>Historical sample reference · supplied and unverified</summary><p>Provided {reference.provenance.providedOn}; observation date unknown. This reference does not replace your current match or note.</p><dl><dt>Original row</dt><dd>{reference.source.original?.rank||'Unknown'}</dd><dt>Supplied title</dt><dd>{reference.source.title}</dd><dt>Proposed recording / ISRC</dt><dd>{reference.source.original?.track||'Unknown'} · {reference.source.original?.matchedIsrc||'Unknown'} · unverified</dd>{#each reference.source.observations as observation(observation.metric)}<dt>Supplied {observation.metric}</dt><dd>{observation.value.toLocaleString()} · observation date unknown</dd>{/each}</dl></details>{/each}</details>
</section>
 <section class="source-next" aria-label="Source next action">{#if humanMoment}<p><strong>{humanMoment.startSeconds}–{humanMoment.endSeconds} seconds</strong> · Human-selected · unverified</p>{:else if selectedMoment}<p><strong>{selectedMoment.startSeconds}–{selectedMoment.endSeconds} seconds</strong> · Saved AI proposal · approximate</p>{:else}<p class="research-meta">Select a moment, or continue with this source alone.</p>{/if}<button class="brief-action" onclick={focusBrief}>Prepare campaign brief</button></section></div><div class="source-working">
 <section class="inspector-step" aria-label="Proposed recording and rationale"><h4>2. Proposed recording</h4>
 {#if match}<p class="selected-recording"><strong>{box.recordings.find(r=>r.id===match.recordingId)?.title||'Unmatched'}</strong> · proposed, unverified</p><p class="match-rationale">{match.rationale}</p>{:else}<p class="research-meta">Choose a recording and explain the connection. This remains a proposal.</p>{/if}
  <details class="match-details" bind:open={matchDetailsOpen}><summary>Recording match and rationale</summary><fieldset disabled={busy||unknown}><legend>Proposed catalog match</legend><label>Recording<select bind:value={recordingId}><option value="">Choose a recording</option>{#each box.recordings as r(r.id)}<option value={r.id}>{r.title}</option>{/each}</select></label><p>Supplied ISRC: {box.recordings.find(r=>r.id===recordingId)?.suppliedIsrc||'Unknown'}. Unverified; choosing a track does not grant audio permission.</p><label>Workstream<select bind:value={workstreamId}><option value="">Choose a workstream</option>{#each box.workstreams as w(w.id)}<option value={w.id}>{w.name}</option>{/each}</select></label><label>Planning stage<select bind:value={stage}>{#each ['new','considering','selected','parked'] as value(value)}<option {value}>{value}</option>{/each}</select></label><label>Why this song fits<textarea bind:value={rationale} rows="3" maxlength="2000"></textarea></label>{#if match&&match.revision!==loadedRevision}<p>A newer match is saved. Your wording is retained.</p><button onclick={()=>{loadedRevision=match.revision;}}>Keep my wording on the current version</button>{/if}<button disabled={!proposalDirty||!recordingId||!workstreamId||!rationale.trim()} onclick={saveMatch}>Save proposed match</button></fieldset></details>
 {#if match?.originalImported}<details><summary>Original supplied proposal</summary><p>{match.originalImported.rationale}</p><p>{box.recordings.find(r=>r.id===match.originalImported.recordingId)?.title}{#if source.original?.stage} · supplied stage: {source.original.stage}{/if}. Supplied proposals do not establish clearance.</p></details>{/if}
<details class="manager-note-tools"><summary>Manager notes ({notes.length})</summary> <section class="inspector-section" aria-label="Shared source notes"><h4>Manager notes</h4>{#each notes as n(n.id)}<blockquote>{n.text}<small>Saved note · revision {n.revision}</small></blockquote>{:else}<p>No shared notes yet.</p>{/each}<label>Your note<textarea bind:value={note} disabled={busy||unknown} maxlength="6000" rows="3"></textarea></label><button disabled={busy||unknown||!note.trim()} onclick={saveNote}>Save source note</button></section>
</details>
 </section>
 <section class="inspector-step" aria-label="Source moment selection"><h4>3. Select a moment</h4>
 {#if humanMoment}<section class="selected-moment" aria-label="Current saved moment"><strong>{humanMoment.title}</strong><p>{humanMoment.startSeconds}–{humanMoment.endSeconds} seconds · Human-selected · unverified</p></section>{:else if selectedMoment}<section class="selected-moment" aria-label="Current saved moment"><strong>{selectedMoment.startSeconds}–{selectedMoment.endSeconds} seconds</strong><p>Saved AI proposal · approximate and unverified</p></section>{:else}<p class="research-meta">Watch the source and save a moment, or review an AI proposal. A source-only brief is also available.</p>{/if}
 {#key source.id}<HumanSelectedMoment {source} recordings={box.recordings} revision={workspace.revision} {request} selectedMomentId={location.momentId||''} onMomentChange={momentId=>onNavigate({...location,view:'inbox',momentId})} onSelection={moment=>humanMoment=moment} onDirtyChange={value=>humanMomentDirty=value} {onSaved} onUseMoment={moment=>{clipMoment={...moment,sourceId:source.id,recordingTitle:box.recordings.find(r=>r.id===moment.recordingId)?.title||'',selectionKey:crypto.randomUUID()};}}/>{/key}<details class="analysis-tools" bind:open={analysisToolsOpen}><summary>AI-assisted moment proposals</summary> {#key source.id}<DefiantPreprocess externalMomentSelected={Boolean(humanMoment)} {source} recordings={box.recordings} {request} selectedMomentId={location.momentId||''} onMomentChange={momentId=>onNavigate({...location,view:'inbox',momentId})} onSelection={(moment,analysisId)=>{selectedMoment=moment;selectedAnalysisId=analysisId;}} onUseMoment={moment=>{clipMoment={...moment,sourceId:source.id,recordingTitle:box.recordings.find(r=>r.id===moment.recordingId)?.title||'',selectionKey:crypto.randomUUID()};}} onDirtyChange={value=>momentDirty=value} onSaved={onSaved}/>{/key}
</details>
  {#key source.id}<DefiantClip {source} proposedMoment={clipMoment?.sourceId&&clipMoment.sourceId!==source.id?null:clipMoment} recordingId={match?.recordingId||''} {request} selectedClipId={location.clipId||''} onClipChange={clipId=>onNavigate({...location,view:'inbox',clipId})} onDirtyChange={value=>clipDirty=value}/>{/key}
</section>
  <section class="report" bind:this={briefSection}><h4>4. Campaign brief</h4><p>Add this source and its saved planning context{location.clipId?' with the selected MP4':''} to a report. Choose a destination there.</p><label>Report title<input bind:this={briefTitle} bind:value={reportTitle} disabled={busy||unknown} maxlength="300" placeholder={source.title}/></label><button disabled={busy||unknown||(!match&&!selectedMoment&&!humanMoment)||proposalDirty||clipDirty||momentDirty||humanMomentDirty||discoveryDirty||Boolean(note.trim())} onclick={report}>Add source to report</button><button disabled={busy||dirty} onclick={()=>onNavigate({...location,view:'map',origin:'talent',focus:'',selected:''})}>Explore graph context</button></section></div></div></div>
 {:else}<h3>Inspect a source</h3><p>Choose a video to see its supplied context and propose a recording match.</p>{/if}</ResearchInspector>{/if}</div>
 {/if}
 {#if (proposalDirty||note.trim()||reportTitle.trim()||preview)&&!unknown}<button disabled={busy} onclick={clear}>Clear match, note and report text</button>{/if}
</section>
<style>
.video-inbox{min-width:0}.catalog-header{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px var(--research-space)}.catalog-header h2{font-size:20px}.catalog-header p{margin:3px 0 0}.journey-label{font-size:10px;letter-spacing:.12em;color:var(--research-muted)}.source-tools-panel{padding-top:10px;min-width:0}.source-tools-panel :global(.discovery){margin:0}.result-count{font-size:12px;color:var(--research-muted);margin:0;padding:8px var(--research-space)}.inbox-layout{display:grid;grid-template-columns:minmax(0,1fr);align-items:start;border-top:1px solid var(--research-line)}.inbox-layout.has-selection{grid-template-columns:minmax(0,1fr)}.source-browser{min-width:0}.source-browser>summary{padding:10px var(--research-space);font-size:12px;font-weight:600;cursor:pointer}.source-browser[open]>summary{border-bottom:1px solid var(--research-line)}.source-workspace{container-type:inline-size}.inspector-composition{display:grid;grid-template-columns:minmax(240px,.85fr) minmax(320px,1.15fr);gap:24px;align-items:start}.source-reading{position:sticky;top:12px;min-width:0}.source-reading:has(.source-evidence[open]){position:static}.source-working{min-width:0}.source-next{padding:10px 0;font-size:12px}.source-next p{margin:0 0 6px}.source-next .brief-action{margin:0}.source-reading .inspector-step{padding-top:0}.source-working>.inspector-step:first-child{padding-top:0}@container(max-width:650px){.inspector-composition{grid-template-columns:minmax(0,1fr);gap:8px}.source-reading{position:static}}@media(max-height:650px){.source-reading{position:static}}.source-tools[open]{flex-basis:100%}.table-scroll{min-width:0;overflow:auto;max-height:calc(100dvh - 280px)}.inbox-layout :global(.research-inspector){border-top:1px solid var(--research-line)}table{width:100%;border-collapse:collapse;font-size:12px}caption{text-align:left;font-weight:600;padding:10px 12px}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--research-line);vertical-align:top}th:first-child{width:48%}th button{background:transparent;border:0;padding:0;min-height:0;color:inherit;text-align:left;line-height:1.4;justify-content:start}small{display:block;color:var(--research-muted);font-size:11px;margin-top:4px}.reset-source-filters{margin-left:8px}.chosen{background:var(--research-selected)}.video-inbox :global(.research-inspector > p){font-size:13px;margin:6px 0}.inspector-step{padding:16px 0;border-bottom:1px solid var(--research-line)}.inspector-step>h4{font-size:14px;margin:0 0 10px}.selected-recording{font-size:13px;margin:4px 0}.match-rationale{font-size:12px;color:var(--research-muted);display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}.manager-note-tools,.analysis-tools{margin:12px 0}.manager-note-tools>summary,.analysis-tools>summary{padding:7px 0}.selected-moment{padding:10px 12px;margin:0 0 10px;background:var(--research-selected);border-radius:6px;font-size:13px}.selected-moment p{margin:4px 0 0;font-size:12px}.brief-action{margin:10px 0}.inspector-step :global(.human-moment){border-bottom:0;padding-top:4px}.analysis-tools :global(.preprocess){border:0;margin:0;padding:10px 0}fieldset{border:1px solid var(--research-line);padding:12px;display:grid;gap:12px}legend{font-size:13px;font-weight:600}dd{margin:4px 0 12px;line-height:1.5}dt{font-size:12px;color:var(--research-muted)}.source-evidence,.match-details,.report{margin:14px 0}.source-evidence summary,.match-details summary{padding:7px 0}.report{padding-top:16px;border-top:1px solid var(--research-line);display:grid;gap:10px}.report button{justify-self:start}.import,.empty{padding:16px;border-bottom:1px solid var(--research-line)}blockquote{margin:12px 0;padding-left:12px;border-left:2px solid var(--research-line)}.observation-history td:first-child{overflow-wrap:anywhere}
@media(max-width:900px){.inbox-layout,.inbox-layout.has-selection{grid-template-columns:minmax(0,1fr)}.table-scroll{max-height:420px}.catalog-header{padding-block:10px}}
</style>
